using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using Verse.AI;using PlayableRecreation;using PRQA;
public static class Command{public static string Run(){var g=(Pawn)Host.State["guest"];var b=(Thing)Host.State["chess"];var sess=GameComponent_Recreation.Current.SessionFor(b);if(sess!=null)GameComponent_Recreation.Current.Remove(sess);g.needs.food.CurLevelPercentage=1;g.needs.rest.CurLevelPercentage=1;g.jobs.EndCurrentJob(JobCondition.InterruptForced);var invite=typeof(TogetherInvite).GetMethod("Invite",BindingFlags.Static|BindingFlags.NonPublic);bool ok=(bool)invite.Invoke(null,new object[]{b.TryGetComp<CompMiniGame>().Game,b,g});int phase=0,start=Find.TickManager.TicksGame,last=-1;Host.Watch=()=>{int t=Find.TickManager.TicksGame;if(t-last<30)return;last=t;File.AppendAllText(Host.Root+"/guest-chair-repro.txt",t+" phase="+phase+" pos="+g.Position+" job="+g.CurJobDef+" joy="+(g.needs.joy==null?"null":g.needs.joy.CurLevelPercentage.ToString())+"\n");if(phase==0&&TogetherToils.Arrived(g,b)){TogetherInvite.ExpireNow(b);phase=1;start=t;}else if(phase==1&&t-start>600){Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Directed debug invitation to chess board with two real chairs: "+ok;}}
